import java.util.Scanner;

public class Main {
    static int n_input, k_input, p_input;
    static int[][] dp;
    static long[] factorials, invs;

    static long binpow(long base, int exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * cur) % p_input;
            cur = (cur * cur) % p_input;
            exp >>= 1;
        }
        return res;
    }

    static int getBit(int x) {
        return x & (-x);
    }

    static void precompute() {
        factorials = new long[n_input + 1];
        invs = new long[n_input + 1];
        factorials[0] = 1;
        for (int i = 1; i <= n_input; ++i)
            factorials[i] = (factorials[i - 1] * i) % p_input;
        invs[n_input] = binpow(factorials[n_input], p_input - 2);
        for (int i = n_input; i >= 1; --i)
            invs[i - 1] = (invs[i] * i) % p_input;
    }

    static long recurse(int current, int S) {
        if (dp[current][S] != -1) return dp[current][S];
        if (S == 0) {
            long res = factorials[n_input];
            for (int i = 1; i <= current; ++i)
                res = (res * (k_input - i + 1)) % p_input;
            dp[current][S] = (int) res;
            return res;
        }
        long result = 0;
        int U = S - getBit(S);
        for (int T = U; T != 0; T = (T - 1) & U)
            result = (result + (invs[S - T] * recurse(current + 1, T)) % p_input) % p_input;
        result = (result + (invs[S] * recurse(current + 1, 0)) % p_input) % p_input;
        dp[current][S] = (int) result;
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n_input = sc.nextInt();
        k_input = sc.nextInt();
        p_input = sc.nextInt();

        int answer = 1;
        for (int i = 1; i <= n_input; ++i)
            answer = (int)((long)answer * k_input % p_input);

        if (n_input % 2 == 0) {
            precompute();
            dp = new int[n_input + 2][1 << n_input];
            for (int i = 0; i <= n_input + 1; ++i)
                for (int j = 0; j < (1 << n_input); ++j)
                    dp[i][j] = -1;
            answer = (answer - (int) recurse(0, n_input) + p_input) % p_input;
        }

        System.out.println(answer);
        sc.close();
    }
}
